import React, { useState, useEffect } from 'react';
import Navbar from '../../components/Navbar';
import { Link } from 'react-router-dom';
import { Users, BookOpen, Clock, UsersSlash } from 'lucide-react';

const PrincipalDashboard = () => {
  // 1. Define the state variables that were missing
  const [hods, setHods] = useState([]);
  const [staff, setStaff] = useState([]);
  const [meetings, setMeetings] = useState([]);
  const [blacklisted, setBlacklisted] = useState([]);

  // 2. This effect prevents the "undefined" error by ensuring variables exist
  useEffect(() => {
    // Logic to fetch your data from the backend would go here
    // Example: axios.get('/api/stats').then(res => { setHods(res.data.hods); ... })
  }, []);

  const stats = [
    { title: 'Total HODs', value: hods.length, icon: Users, link: '/manage-hods' },
    { title: 'Total Staff', value: staff.length, icon: BookOpen, link: '/manage-staff' },
    { title: 'Total Meetings', value: meetings.length, icon: Clock, link: '/all-meetings' },
    { title: 'Blacklisted Users', value: blacklisted.length, icon: UsersSlash, link: '/principal/blacklist' },
  ];

  return (
    <div className="principal-dashboard-wrapper">
      <Navbar />
      <div className="principal-dashboard-container">
        <h1 style={{ textAlign: 'center', margin: '20px 0' }}>Welcome, Principal</h1>

        <div className="dashboard-grid">
          {stats.map((stat, index) => (
            <div key={index} className="dashboard-card">
              <stat.icon size={48} color="#007bff" />
              <h2>{stat.title}</h2>
              <p className="stat-value">{stat.value}</p>
              <Link to={stat.link} className="manage-link">View/Manage</Link>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default PrincipalDashboard;
